template:
fn find_user(id: i32) -> Option<&'static str> {
    if id == 1 { Some("Alice") } else { None }
}

fn get_name(
    id: i32,
) -> Result<&'static str, &'static str> {
    let u = find_user(id)
        ⟦slot1⟧
        ⟦slot2⟧;
    Ok(u)
}

fn main() { let _ = get_name(1); }

tests:
#[test]
fn test_get_name() {
    assert_eq!(get_name(1), Ok("Alice"));
    assert_eq!(get_name(2), Err("not found"));
}
